{
  "technical_and_design_decisions": [
    "Implement the Receptor integration as a Java client library using the existing Receptor API contract and an HTTP-based transport abstraction.",
    "Refactor stream and job definition repositories behind interfaces so persistence and module deployment concerns are separate.",
    "Define a runtime SPI with capability-oriented interfaces and provide an initial Cloud Foundry-compatible implementation while preserving an extension point for on-premises and Mesos runtimes.",
    "Use a transactional relational persistence implementation for stream metadata, with repository state sufficient to reconstruct and restart streaming pipelines after failure.",
    "Implement streaming-pipeline support through adapters around the existing XD and Spark/Spark Streaming integration points rather than coupling core pipeline definitions directly to Spark classes.",
    "Represent Sqoop import options as typed or named job properties and retain backward compatibility with the existing --args option where practical.",
    "Document user-facing behavior in the project documentation format already used by the repository, with examples for escaping, nested workflows, and parameterized import options.",
    "Add unit tests for new components and integration tests for repository persistence, runtime selection, Receptor calls, and streaming-pipeline lifecycle behavior."
  ],
  "assumptions": [
    "An existing Spring XD codebase, build system, test framework, configuration model, and module deployment framework are available and can be extended without major platform migration.",
    "The Receptor API is sufficiently documented or discoverable from the referenced Java client, and no new Receptor server functionality is required.",
    "The increment is implemented by one developer, so estimates represent total person-hours and include normal local debugging and code review preparation but not elapsed calendar time.",
    "A relational database and transaction abstraction already supported by the project can be used for the persistent stream repository; database provisioning and production operations are out of scope.",
    "The initial runtime SPI implementation targets the currently supported Cloud Foundry/Diego deployment path; complete production implementations for Mesos and every on-premises environment are out of scope.",
    "Spark and Spark Streaming dependencies and compatible versions are already available; the work is limited to XD pipeline integration and compatibility updates.",
    "Requirements do not specify detailed API schemas, migration rules, security changes, performance targets, or UI changes, so existing project conventions are used.",
    "Documentation work covers authoring and verification of examples, not a full documentation-site redesign or translation.",
    "Effort includes implementation, developer-authored tests, local integration verification, and regression fixes, but excludes formal external acceptance testing and release operations."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Increment planning and codebase analysis",
      "activity_description": "Inspect existing stream/job repositories, deployment abstractions, Receptor-related code, Spark integration, Sqoop option handling, persistence conventions, and test structure; produce an implementation plan and identify affected APIs.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A2",
      "activity_name": "Implement Java Receptor client",
      "activity_description": "Create the Java client for required Receptor API calls, including request/response models, transport handling, authentication/configuration integration, error mapping, and unit tests for representative Diego interactions.",
      "most_likely_effort": 64
    },
    {
      "activity_id": "A3",
      "activity_name": "Refactor stream and job definition repositories",
      "activity_description": "Separate definition storage and retrieval responsibilities from module deployment concerns, introduce or adjust repository interfaces, migrate existing callers, preserve compatibility, and add regression tests.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A4",
      "activity_name": "Define pluggable runtime SPI",
      "activity_description": "Design runtime lifecycle and deployment interfaces, runtime selection/configuration, capability and error contracts, and implement the initial target runtime adapter with unit and integration-level tests.",
      "most_likely_effort": 48
    },
    {
      "activity_id": "A5",
      "activity_name": "Implement persistent stream repository",
      "activity_description": "Create the relational persistence model and repository implementation for stream metadata and runtime state, add transactional behavior and restart/recovery lookup operations, handle schema initialization or migration, and test failure recovery scenarios.",
      "most_likely_effort": 56
    },
    {
      "activity_id": "A6",
      "activity_name": "Document Sqoop escape-quote behavior",
      "activity_description": "Add clear documentation and examples explaining double escaping of the Sqoop null or escape value, including the distinction between shell quoting and job-property values.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A7",
      "activity_name": "Implement streaming pipeline support",
      "activity_description": "Add or update streaming pipeline definitions and execution integration for current XD and Spark/Spark Streaming specifications, including configuration translation, lifecycle handling, compatibility checks, and focused tests.",
      "most_likely_effort": 80
    },
    {
      "activity_id": "A8",
      "activity_name": "Document nested batch jobs and workflows",
      "activity_description": "Create reference documentation with configuration examples, nesting rules, execution semantics, limitations, and troubleshooting guidance for nested batch jobs and workflows in XD.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A9",
      "activity_name": "Parameterize Sqoop import options",
      "activity_description": "Expose import options as named configurable properties, update parsing and command construction, remove or de-emphasize the confusing --args requirement while preserving compatibility where feasible, and add validation and tests.",
      "most_likely_effort": 48
    },
    {
      "activity_id": "A10",
      "activity_name": "Cross-cutting automated tests",
      "activity_description": "Add or complete unit, persistence, API-client, SPI, pipeline, and option-parsing tests; include mocks or stubs for external Receptor, runtime, database, and Spark interactions.",
      "most_likely_effort": 48
    },
    {
      "activity_id": "A11",
      "activity_name": "End-to-end integration and regression verification",
      "activity_description": "Run representative workflows across the modified repositories, runtime selection, persistent stream restart, Receptor communication, Spark streaming integration, nested jobs, and Sqoop options; diagnose and fix integration regressions.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A12",
      "activity_name": "Packaging, build updates, and increment completion",
      "activity_description": "Update dependencies, build descriptors, configuration defaults, migration resources, generated documentation references, release notes, and final clean-build verification.",
      "most_likely_effort": 16
    }
  ],
  "reported_total": {
    "most_likely_effort": 468
  }
}

